INSERT INTO `products` (`id`, `name`, `slug`, `description`, `price`, `category`, `image`, `createdAt`, `stock`, `gallery`, `updatedAt`, `buyNowUrl`) VALUES
(1, 'Hot Pink Printed Indo-Fusion Co-Ord Set with Jacket Layer', 'hot-pink-printed-indo-fusion-co-ord-set-with-jacket-layer', 'Elevate your ethnic wardrobe with this stunning Hot Pink Printed Indo-Fusion Co-Ord Set with Jacket Layer, a perfect blend of modern style and traditional charm. Designed for the contemporary woman, this three-piece ensemble effortlessly combines comfort with elegance.\r\n\r\nThe set features a stylish sleeveless or cropped inner top, paired with wide-leg trousers that offer a flattering silhouette and all-day comfort. Completing the look is a beautifully printed long jacket layer, adorned with ethnic-inspired patterns and intricate detailing, adding a graceful and sophisticated touch.\r\n\r\nCrafted to make a bold statement, the vibrant hot pink color enhances your overall look, making it ideal for festive occasions, weddings, brunches, or special gatherings. The fusion design ensures versatility, allowing you to style it both traditionally and in a modern way.\r\n\r\nKey Features:\r\nThree-piece set: Top, trousers & long jacket\r\nEye-catching ethnic prints with modern fusion design\r\nComfortable wide-leg pants with easy fit\r\nLightweight and breathable fabric\r\nPerfect for festive wear, parties, and casual celebrations', 199.00, 'kurti', '1784287226914-750974168.webp', '2026-07-23 10:07:14', 20, '[\"1784287226921-694607105.webp\",\"1784287226927-435283794.webp\"]', '2026-07-23 10:07:14', NULL),
(2, 'Cream Mirror-Work Short Kurti & Pant Set with Contrasting Pink Yoke', 'exclusive-party-wear-dress', '1. PRODUCT TITLE\r\nTeal Green Hand-Embroidered Anarkali Set with Dupatta & Golden Lace Detailing\r\n\r\n2. PRODUCT DESCRIPTION\r\nThis teal green Anarkali set beautifully blends festive charm with soft elegance, making it a standout choice for celebrations, traditional gatherings, and cultural events. The Anarkali features a classic round neckline adorned with delicate golden lace that adds a soft shimmer framing the face gracefully. Its long sleeves carry the same refined lace detailing at the cuffs, creating a cohesive and regal aesthetic from top to bottom.\r\n\r\nThe body of the Anarkali is sprinkled with delicate zari-embroidered floral motifs that elevate the entire look with a subtle festive glow. The flare is wide and fluid, giving the outfit a graceful flow with every step—perfect for twirling moments and effortless movement. The hemline is enriched with a broad golden lace border, enhancing the richness of the piece and giving it a grand, traditional finish.\r\n\r\nThe matching dupatta complements the outfit perfectly, designed in a lightweight sheer fabric featuring coordinated floral embroidery and a golden lace border that completes the ensemble. Its soft drape allows multiple styling options, adding versatility and elegance to the outfit.\r\n\r\nThis set is ideal for those who appreciate understated glamour—something that feels luxurious yet comfortable and beautifully feminine.\r\n\r\n3. FABRIC & MATERIAL (MORE DETAILS)\r\n\r\nAnarkali Fabric: Premium silk-blend with a crisp, elegant fall\r\n\r\nDupatta Fabric: Soft organza/net with embroidered motifs\r\n\r\nEmbroidery: Zari thread-work floral buttis across the body\r\n\r\nBorders: Finely crafted golden lace on neckline, sleeves & hem\r\n\r\nComfort Lining: Breathable inner lining for full-day wear\r\n\r\nFinish: High-quality stitching for structured flare & durability\r\n\r\n4. COLOR & EMBROIDERY DETAILS\r\n\r\nColor: Teal green with rich gold accents\r\n\r\nNeckline: Golden lace border for a radiant frame\r\n\r\nSleeves: Coordinated lace detailing\r\n\r\nFloral Motifs: Zari-embroidered golden flowers throughout\r\n\r\nHemline: Wide ornate lace border for a premium festive look\r\n\r\nDupatta: Floral embroidery + golden lace finish\r\n\r\nSTYLING OPTIONS\r\n\r\nPair with heavy jhumkas or chandbalis to complement the golden embroidery\r\n\r\nOpt for soft waves or a sleek straight hairstyle to enhance the neckline\r\n\r\nCream-gold jutis or metallic heels elevate the traditional appeal\r\n\r\nAdd bangles or a kada set for a complete festive-ready look\r\n\r\nWHY CHOOSE THIS PRODUCT\r\n\r\nElegant color that suits all skin tones\r\n\r\nSoft yet festive embroidery for a rich, traditional look\r\n\r\nLightweight, comfortable & perfect for long events\r\n\r\nHigh-quality lace detailing adds sophistication\r\n\r\nVersatile styling—great for festivals, parties & family functions\r\n\r\nOCCASION & STYLING TIPS (SHORT)\r\nPerfect for festivals, poojas, weddings, sangeet, and family gatherings. Style with gold jewelry for an instantly elevated festive look.\r\n\r\nSHOWCASE (DISCLAIMER)\r\nThis product description is provided solely to help customers understand the features, materials, and styling of the item.\r\nImages and product details are for illustrative reference only. Actual colors, textures, and finishing may vary slightly due to lighting, screen settings, and availability. This description does not constitute a guarantee or warranty of the product.', 199.00, 'kurti', '1784287473506-214025606.webp', '2026-07-23 10:07:14', 20, '[\"1784287473506-313174133.webp\"]', '2026-07-23 10:07:14', NULL),
(3, 'Women’s Light Green Embroidered Kurti with Floral Threadwork – Elegant Long-Sleeve Ethnic Casualwear', 'women-s-light-green-embroidered-kurti-with-floral-threadwork-elegant-long-sleeve-ethnic-casualwear', 'Grace your wardrobe with this refined light green  kurti, designed to deliver a balance of elegance and comfort for everyday  ethnic styling. With its soft pastel hue and intricately embroidered details, this long-sleeve garment effortlessly transitions from semi-casual gatherings to day-to-day wear with cultural flair.\r\nThe kurti features delicate floral embroidery in hues of pink and green, arranged gracefully across the upper bodice and sleeves. The threadwork incorporates both botanical and vine-inspired patterns, adding texture and a handcrafted touch to the overall silhouette. The embroidery is concentrated near the neckline and cuffs, offering a balanced visual experience that draws attention without overpowering the look.\r\nDesigned with full sleeves and a buttoned front placket, the kurti presents a tailored yet breathable fit. The fabric appears light and flowy—likely a cotton or cotton-blend base—ensuring ease of movement and comfort through changing weather conditions. The cut follows a straight silhouette that flatters a variety of body types and works beautifully when styled with leggings, palazzos, or classic churidar pants.\r\nIdeal for casual outings, office wear, cultural get-togethers, or boutique rack displays, this kurti pairs well with minimalistic accessories like metallic jhumkas, bangles, or a soft dupatta. You can elevate the ensemble further with wedges or embroidered flats, depending on the tone you’re curating.\r\nThe soft, blurred background of the presentation keeps the focus squarely on the garment, making it suitable for product listings, editorial photoshoots, or social media rollouts. Its pastel palette and handcrafted embroidery appeal to shoppers who value timeless ethnicwear with thoughtful detailing.\r\nWhether you’re building a seasonal collection, styling for customer lookbooks, or updating catalog offerings, this embroidered kurti is a compelling addition to your ethnicwear lineup—promising comfort, cultural elegance, and styling versatility.', 149.00, 'kurti', '1784287569964-249908012.webp', '2026-07-23 10:07:14', 26, '[\"1784287569964-347838070.webp\",\"1784287569967-616458891.webp\"]', '2026-07-23 10:07:14', NULL),
(4, 'Graceful Blue Embroidered Lawn Co-Ord Set – Where Comfort Meets Contemporary CharmDesigner outfit set', 'graceful-blue-embroidered-lawn-co-ord-set-where-comfort-meets-contemporary-charmdesigner-outfit-set', 'Discover the effortless charm of our elegant blue two-piece lawn suit – a beautifully tailored ensemble made for the woman who moves with grace and lives with purpose. This outfit blends tradition and modernity with its relaxed silhouette, delicate embroidery, and breathable fabric, making it an ideal pick for warm days and breezy evenings alike.\r\n\r\nCasual suit\r\nDesigner clothing\r\nThe soft, flowing lawn fabric drapes beautifully, offering all-day comfort and understated sophistication. The top features a simple yet flattering V-neckline, accented with a minimalist button placket. Long sleeves and a loose fit ensure ease of movement, while the hem steals the spotlight with intricate cutwork embroidery that adds a subtle touch of femininity and elegance.\r\n\r\nPaired with wide-leg trousers in a matching hue, the co-ord set creates a cohesive, polished look that’s effortlessly stylish. Whether you’re attending a casual meet-up, a relaxed family dinner, or simply enjoying your everyday routine, this outfit offers the perfect balance of chic and cozy.\r\n\r\nElevate your style by pairing it with neutral heels, a structured handbag, and sleek sunglasses—just like in the photo—and you’re ready to take on the day with poise. Its rich blue tone works across all seasons, offering versatility and timeless appeal in your wardrobe.', 129.00, 'kurti', '1784287789105-306294506.webp', '2026-07-23 10:07:14', 8, '[\"1784287789106-572854907.webp\",\"1784287789107-935813451.webp\"]', '2026-07-23 10:07:14', NULL),
(5, 'Blue Floral Embroidered Kurti Set', 'blue-floral-embroidered-kurti-set', 'Grace your wardrobe with timeless elegance and modern flair with our Teal Blue Floral Embroidered Kurti Set. Designed for women who appreciate a blend of sophistication and tradition, this ensemble makes a graceful statement whether you’re dressing up for a festive gathering, a cultural celebration, or a semi-formal occasion.\r\n\r\nThe set includes a matching dupatta, sheer and elegant, adorned with a complementing floral print and delicate beadwork along the borders. The dupatta adds an ethereal layer of beauty, floating gracefully with every movement. Its sheer design adds dimension and softness, making the entire outfit more graceful and festive.\r\n\r\noutfit ideal for both warm and mild seasons. A round neckline ensures a classic look that pairs beautifully with both traditional jewelry and contemporary accessories. Whether you’re opting for silver jhumkas and bangles or going minimalist, this kurti set adapts to your style effortlessly.\r\n\r\nKey Features:\r\n\r\nRich teal blue silk-blend fabric\r\n\r\nElegant floral embroidery on kurti\r\n\r\nDecorative button detailing\r\n\r\nMatching sheer dupatta with floral prints\r\n\r\nComfortable three-quarter sleeves\r\n\r\nIdeal for festive, formal, or semi-formal occasions\r\n\r\nAvailable in sizes S to XXL', 129.00, 'kurti', '1784287917335-273596195.webp', '2026-07-23 10:07:14', 9, '[\"1784287917336-955529375.webp\"]', '2026-07-23 10:07:14', NULL),
(6, 'Stylish Pink and Orange Printed Kurtis', 'stylish-pink-and-orange-printed-kurtis', 'Step into effortless elegance with this Stylish Pink and Orange Printed Kurti, a perfect blend of traditional charm and modern flair. Crafted from soft, breathable fabric, this kurti features vibrant floral and abstract prints in shades of pink and orange that add a festive pop to your wardrobe.\r\n\r\nWhether you’re dressing up for a casual day out, a festive celebration, or office wear, this kurti promises all-day comfort with its relaxed fit and lightweight design. Pair it with leggings, palazzos, or jeans for a versatile ethnic look that never goes out of style.\r\n\r\nDesigned for women who love vibrant colors and graceful silhouettes, this kurti combines fashion-forward styling with Indian ethnic heritage.', 149.00, 'kurti', '1784287992792-213208618.webp', '2026-07-23 10:07:14', 6, '[\"1784287992793-916571755.webp\"]', '2026-07-23 10:07:14', NULL),
(7, 'Elegant White & Pink Anarkali Suit with Net Dupatta and Sharara', 'elegant-white-pink-anarkali-suit-with-net-dupatta-and-sharara', 'Grace meets grandeur with this Elegant White & Pink Anarkali Suit, crafted for the modern woman who embraces tradition with a contemporary flair. The intricately embroidered Anarkali kurta is paired with a beautifully flared sharara and a lightweight net dupatta, creating a look that’s both regal and romantic.\r\nPerfect for festive occasions, weddings, sangeet, or formal gatherings, this ensemble combines comfort with elegance, making you the center of attention wherever you go.\r\n\r\nMade from premium-quality fabric, the Anarkali features subtle white embroidery on a soft pink base, accentuating your silhouette with timeless charm. The sheer dupatta with delicate border work adds a layer of grace and completes the look.', 149.00, 'kurti', '1784288109296-103541824.webp', '2026-07-23 10:07:14', 10, '[\"1784288109296-415055466.webp\"]', '2026-07-23 10:07:14', NULL),
(8, 'Cotton printed embroidery straight kurti set', 'cotton-printed-embroidery-straight-kurti-set', 'Elevate your everyday and festive wardrobe with this elegant Cotton Printed Embroidery Straight Kurti Set. Crafted from soft, breathable cotton, this outfit blends traditional charm with modern flair. The straight-cut kurti features delicate embroidery on the neckline and sleeves, complemented by subtle all-over prints for a timeless appeal.\r\n\r\nPaired with a matching cotton pant and coordinated dupatta, this 3-piece set offers complete comfort and graceful styling—ideal for office wear, casual outings, family gatherings, or festive celebrations.\r\n\r\nDesigned for all-day wear with a flattering fit, this kurti set is a must-have for women who love effortless elegance.', 149.00, 'kurti', '1784288228606-287965563.webp', '2026-07-23 10:07:14', 9, '[\"1784288228606-551251970.webp\"]', '2026-07-23 10:07:14', NULL),
(9, 'Beautiful Pure Cotton Handwoven Kurta set', 'beautiful-pure-cotton-handwoven-kurta-set', 'Elevate your ethnic wardrobe with this Beautiful Pure Cotton Handwoven Kurta Set, crafted by skilled artisans using traditional handloom techniques. Designed for comfort and elegance, this set features a breathable, soft cotton fabric that feels gentle on the skin—perfect for all-day wear in any season.\r\n\r\nWith its minimalistic charm and timeless design, the kurta set blends cultural heritage with modern fashion. Ideal for festive occasions, workwear, or casual outings, it brings a unique blend of simplicity, sustainability, and style to your look.', 149.00, 'kurti', '1784288305510-726393520.webp', '2026-07-23 10:07:14', 12, '[\"1784288305510-676624370.webp\"]', '2026-07-23 10:07:14', NULL),
(10, 'Bountiful Floral Printed Cotton Kurti in White, Yellow, Blue, and Purple', 'bountiful-floral-printed-cotton-kurti-in-white-yellow-blue-and-purple', 'Elevate your everyday elegance with this Bountiful Floral Printed Cotton Kurti, a delightful blend of comfort, color, and charm. Crafted from premium breathable cotton, this kurti features an enchanting floral print in soothing white, vibrant yellow, cool blue, and graceful purple—perfect for sunny days, casual outings, or festive brunches.\r\n\r\nDesigned with a relaxed straight cut, 3/4th sleeves, and a modest round neckline, this kurti brings together traditional grace and contemporary flair. Whether paired with leggings, palazzos, or denim, it’s a wardrobe essential for women who love effortless style with a splash of color.\r\n\r\nMade for all-day wear, this kurti ensures a flattering fit and long-lasting comfort—making it your go-to for both work and weekend looks.', 199.00, 'kurti', '1784288368706-12356412.webp', '2026-07-23 10:07:14', 7, '[\"1784288368707-803693937.webp\"]', '2026-07-23 10:07:14', NULL),
(11, 'Elegant Chanderi Silk Dabu Handblock Print Saree with Matching Blouse', 'elegant-chanderi-silk-dabu-handblock-print-saree-with-matching-blouse', 'Step into timeless elegance with this Chanderi Silk Dabu Handblock Print Saree, a perfect blend of tradition and contemporary grace. Handcrafted using the age-old Dabu mud resist technique, this saree showcases intricate floral and geometric patterns created by skilled artisans. The lightweight and breathable Chanderi silk fabric drapes beautifully, offering both sophistication and comfort for festive occasions, weddings, or elegant daywear.\r\n\r\nPaired with a matching unstitched blouse piece, this saree is a celebration of India’s rich textile heritage. Its natural dyes, eco-conscious printing method, and artisanal finesse make it a standout addition to any conscious wardrobe.\r\n\r\nWhether you’re attending a traditional function or want to elevate your everyday ethnic look, this saree delivers effortless charm.', 249.00, 'Saree', '1784289048880-614145556.webp', '2026-07-23 10:07:14', 80, '[\"1784289048881-397772695.webp\"]', '2026-07-23 10:07:14', NULL),
(12, 'Marigold Yellow Chiffon Printed & Cutdana Work Draped Saree Set', 'marigold-yellow-chiffon-printed-cutdana-work-draped-saree-set', 'Turn heads with our Marigold Yellow Chiffon Printed & Cutdana Work Draped Saree Set – a timeless blend of effortless grace and modern elegance. Crafted in lightweight chiffon, this pre-draped saree features delicate floral prints and hand-embellished Cutdana detailing that adds subtle shimmer. The rich marigold yellow hue exudes festive charm, perfect for weddings, cocktail evenings, or special celebrations.\r\n\r\nPaired with a matching designer blouse, the set is tailored for comfort and style. The pre-stitched drape allows for easy wear and a flawless silhouette—making it ideal for contemporary women who love classic fashion with a twist.', 199.00, 'Saree', '1784289109671-724601299.webp', '2026-07-23 10:07:14', 70, '[\"1784289109672-461673578.webp\"]', '2026-07-23 10:07:14', NULL),
(13, 'Mustard Brown Soft Cotton Saree with Ikat Prints – A Heritage of Elegance', 'mustard-brown-soft-cotton-saree-with-ikat-prints-a-heritage-of-elegance', 'Elevate your ethnic wardrobe with our Mustard Brown Soft Cotton Saree, adorned with timeless Ikat prints that speak of rich tradition and modern grace. Woven from ultra-soft, breathable cotton, this saree ensures all-day comfort while making a statement of refined heritage. Whether for festive occasions, cultural gatherings, or daily elegance, this saree embodies artisanal charm with a contemporary edge. Pair it with antique silver jewelry and flats for an effortlessly graceful look.\r\n\r\nHandcrafted with love, this piece is more than fashion—it’s a story woven in threads.', 149.00, 'Saree', '1784289202748-370330163.webp', '2026-07-23 10:07:14', 100, '[\"1784289202748-861815924.webp\"]', '2026-07-23 10:07:14', NULL),
(14, 'Elegant black and white printed saree – timeless style and effortless charm', 'elegant-black-and-white-printed-saree-timeless-style-and-effortless-charm', 'Experience timeless elegance with our black and white printed saree, a perfect blend of classic charm and modern minimalism. Crafted from premium-quality fabric, this lightweight saree features graceful monochrome prints that make a bold yet refined statement. Whether it’s a festive occasion, office wear, or a casual outing, this versatile piece enhances your look with effortless sophistication.\r\n\r\nDesigned for the woman who values tradition with a twist, this saree drapes beautifully, offers breathable comfort, and transitions seamlessly from day to night wear. Pair it with oxidized silver jewelry or a sleek blouse for a look that turns heads every time.\r\n\r\nIdeal for gifting, styling, or everyday grace—this saree defines timeless fashion for the modern Indian woman.', 199.00, 'Saree', '1784289317737-947539620.webp', '2026-07-23 10:07:14', 22, '[\"1784289317737-270480802.webp\"]', '2026-07-23 10:07:14', NULL),
(15, 'Rama Green Threadwork Soft Silk Saree – An Exquisite Blend of Elegance and Artistry', 'rama-green-threadwork-soft-silk-saree-an-exquisite-blend-of-elegance-and-artistry', 'Experience timeless grace in our Rama Green Threadwork Soft Silk Saree, a perfect blend of luxury, tradition, and intricate craftsmanship. Woven from premium soft silk, this saree features elaborate threadwork embroidery that showcases fine detailing and ethnic charm. The soothing rama green hue enhances every complexion, while the lightweight texture ensures comfort all day long—ideal for weddings, festive occasions, and cultural celebrations.\r\n\r\nWhether you’re dressing for an elegant event or gifting someone special, this saree promises sophistication and versatility. Pair it with statement jewelry and heels for a regal look, or keep it minimal for understated elegance.', 199.00, 'Saree', '1784289374138-149764487.webp', '2026-07-23 10:07:14', 8, '[\"1784289374139-129970343.webp\"]', '2026-07-23 10:07:14', NULL),
(16, 'BEAUTIFUL BURGUNDY COLOUR PRE-DRAPED 1 MINUTE SAREE', 'beautiful-burgundy-colour-pre-draped-1-minute-saree', 'Turn every head in the room with our Beautiful Burgundy Pre-Draped Saree – the ultimate blend of tradition, glamour, and effortless modern style. Designed for today’s fast-paced woman, this 1-minute saree lets you get dressed and dazzle without the drape drama.\r\n\r\nCrafted from premium wrinkle-free fabric, this ready-to-wear saree features elegant pleats, a flattering pallu fall, and a rich burgundy hue that suits every skin tone. Perfect for weddings, parties, receptions, or festive events — simply pair with your favorite blouse and you’re ready to shine!\r\n\r\nWhether you’re a bride, bridesmaid, or a guest, this saree gives you the charm of six yards in just 60 seconds.', 199.00, 'Saree', '1784289453471-95807329.webp', '2026-07-23 10:07:14', 23, '[\"1784289453471-639318777.webp\"]', '2026-07-23 10:07:14', NULL),
(17, 'Red Soft Georgette Saree with Heavy Embroidery Work – A Stunning Celebration of Elegance', 'red-soft-georgette-saree-with-heavy-embroidery-work-a-stunning-celebration-of-elegance', 'Step into the spotlight with this Red Soft Georgette Saree, exquisitely adorned with heavy embroidery work that captures the essence of traditional Indian elegance. Designed for weddings, festive occasions, and parties, this saree blends lightweight comfort with luxurious appeal.\r\n\r\nCrafted from premium georgette fabric, it drapes beautifully on every body type, while intricate zari, resham, and sequin embroidery add a touch of royalty. Pair it with statement jewelry and heels for a graceful and glamorous look.\r\n\r\nWhether you’re the bride, bridesmaid, or guest — this saree ensures all eyes are on you.', 199.00, 'Saree', '1784289545876-651596083.webp', '2026-07-23 10:07:14', 45, '[\"1784289545876-738782849.webp\"]', '2026-07-23 10:07:14', NULL),
(18, 'Sugam Swar Elegant Pink Saree – A Timeless Statement of Grace', 'sugam-swar-elegant-pink-saree-a-timeless-statement-of-grace', 'Elevate your ethnic wardrobe with the Sugam Swar Elegant Pink Saree, a timeless blend of tradition and sophistication. Woven with rich detail and crafted from premium fabric, this saree showcases delicate craftsmanship, elegant draping, and a universally flattering pink tone that radiates femininity and charm. Perfect for weddings, festivals, or formal occasions, it’s more than just attire—it’s a statement of grace and cultural elegance.\r\n\r\nDesigned to offer both comfort and class, this saree effortlessly combines heritage with contemporary appeal. Whether you’re a bride, bridesmaid, or a connoisseur of traditional fashion, the Sugam Swar Elegant Pink Saree guarantees compliments with every step.', 199.00, 'Saree', '1784289629944-928546543.webp', '2026-07-23 10:07:14', 90, '[\"1784289629944-765445778.webp\"]', '2026-07-23 10:07:14', NULL),
(19, 'Red Georgette Saree with Parsi Gara Work', 'red-georgette-saree-with-parsi-gara-work', 'Elevate your ethnic wardrobe with this exquisite Red Georgette Saree featuring intricate Parsi Gara embroidery—a timeless expression of handcrafted elegance. Made from lightweight, flowy georgette, this saree drapes beautifully, offering grace and comfort in every pleat. The Parsi Gara work, known for its delicate floral and bird motifs, is meticulously hand-embroidered by skilled artisans, making each piece a work of wearable art.\r\n\r\nWhether you’re attending a wedding, festive celebration, or formal event, this red georgette saree blends heritage craftsmanship with modern appeal. Pair it with statement jewelry and traditional heels to complete your regal look. A true heirloom that transcends seasons and trends.', 299.00, 'Saree', '1784289687662-799350129.webp', '2026-07-23 10:07:14', 70, '[\"1784289687667-399745871.webp\"]', '2026-07-23 10:07:14', NULL),
(20, 'onion colour satin saree with heavy handwork', 'onion-colour-satin-saree-with-heavy-handwork', 'Elevate your ethnic wardrobe with this luxurious onion colour satin saree, exquisitely embellished with heavy handwork detailing. Crafted from rich satin fabric, this saree flows with graceful sheen and softness, offering both comfort and elegance. The intricate hand embroidery adds a royal touch, making it a perfect choice for weddings, receptions, festivals, and evening parties.\r\n\r\nThe beautiful onion pink shade, a unique fusion of blush and mauve, complements every skin tone and makes you stand out in any crowd. Pair it with statement jewellery and heels for a glamorous ethnic look.', 199.00, 'Saree', '1784289746636-66675393.webp', '2026-07-23 10:07:14', 33, '[\"1784289746636-405359395.webp\"]', '2026-07-23 10:07:14', NULL),
(21, 'STUNNING DESIGNER LEHANGA ( OFF WHITE)', 'stunning-designer-lehanga-off-white', 'STUNNING DESIGNER LEHANGA ( OFF WHITE)', 199.00, 'Lehenga Choli', '1784289962227-446544530.webp', '2026-07-23 10:07:14', 30, '[\"1784289962235-312499923.webp\"]', '2026-07-23 10:07:14', NULL),
(22, 'Embroidered Mauve Designer Blouse & Dupatta Set – Premium Mirror & Thread Work', 'embroidered-mauve-designer-blouse-dupatta-set-premium-mirror-thread-work', 'This elegant mauve embroidered blouse and dupatta set is a perfect pick for festive occasions, weddings, parties, and traditional events. The set features rich mirror work, intricate floral thread embroidery, and a premium designer finish that instantly enhances your overall look.\r\n\r\nThe blouse is beautifully crafted with heavy embroidery on the front and the sleeves, giving it a luxurious appearance. The back includes a stylish tie-up design. The matching dupatta comes with a delicately embroidered border, making the entire set look graceful and complete.\r\n\r\nMade from soft and comfortable fabric, this set is ideal for long wear and keeps you looking stylish without compromising comfort.', 150.00, 'Lehenga Choli', '1784290082927-909459333.webp', '2026-07-23 10:07:14', 70, '[\"1784290082928-330749387.webp\",\"1784290082929-592992326.webp\"]', '2026-07-23 10:07:14', NULL),
(23, 'Multi Color Silk Embroidery Work Latest Navratri Lehenga Choli', 'multi-color-silk-embroidery-work-latest-navratri-lehenga-choli', 'Step into the spotlight this Navratri with our Multi-Color Silk Embroidery Work Lehenga Choli, designed to make you the center of attention at every Garba and Dandiya night. Crafted from premium quality silk, this stunning ensemble features intricate multicolor thread embroidery, mirror work accents, and a vibrant flared silhouette that celebrates traditional elegance with a modern twist.\r\n\r\nPerfect for the nine nights of celebration, this lehenga choli blends comfort, culture, and couture. Whether you’re twirling on the dance floor or making an entrance at a festive gathering, this designer Navratri lehenga ensures unmatched grace and glamour. Pair it with oxidized jewelry and traditional juttis for a complete festive look.\r\n\r\nIdeal for: Navratri 2025, Dandiya nights, festive events, weddings, or traditional parties.', 149.00, 'Lehenga Choli', '1784290160696-33720827.webp', '2026-07-23 10:07:14', 11, '[\"1784290160697-105935754.webp\"]', '2026-07-23 10:07:14', NULL),
(24, 'Multi Color Thread Mirror Embellished Maslin Cotton Lehenga Set', 'multi-color-thread-mirror-embellished-maslin-cotton-lehenga-set', 'Make a statement with this Multi-Color Thread Mirror Embellished Lehenga Set, beautifully crafted in breathable Maslin cotton fabric. Featuring intricate thread embroidery and mirror embellishments, this lehenga exudes elegance and charm—perfect for festive occasions, weddings, sangeet, or traditional celebrations.\r\n\r\nThe lightweight Maslin cotton ensures comfort without compromising on richness. Paired with a complementary blouse and dupatta, this lehenga set is ideal for women who love effortless ethnic fashion with a modern twist.\r\n\r\nWhether you’re attending a daytime function or evening gala, this ensemble will have you glowing with grace.', 249.00, 'Lehenga Choli', '1784290272141-644526805.webp', '2026-07-23 10:07:14', 70, '[\"1784290272148-378265604.webp\"]', '2026-07-23 10:07:14', NULL),
(25, 'Sky Blue Sequins Georgette Wedding Wear Lehenga Choli – Radiant Elegance for Your Special Day', 'sky-blue-sequins-georgette-wedding-wear-lehenga-choli-radiant-elegance-for-your-special-day', 'Make your special day truly unforgettable with our Sky Blue Sequins Georgette Wedding Wear Lehenga Choli — a stunning blend of elegance, charm, and tradition. Crafted from premium georgette fabric, this lehenga features intricate sequin embellishments that shimmer with every step you take. The soft sky blue hue exudes serenity and grace, making it an ideal choice for bridal events, sangeet nights, receptions, and engagement ceremonies.\r\n\r\nThe semi-stitched lehenga ensures a perfect fit, while the matching choli and dupatta complete this luxurious ensemble. Lightweight yet luxurious, this outfit offers unmatched comfort and style for long celebrations.\r\n\r\nPerfect for the modern bride or bridesmaid who wants to shine with timeless sophistication.', 149.00, 'Lehenga Choli', '1784290356236-12822840.webp', '2026-07-23 10:07:14', 22, '[\"1784290356237-390764240.webp\"]', '2026-07-23 10:07:14', NULL),
(26, 'Maroon Anarkali Lucknowi Chikankari Work Lehenga – A Beautiful Fusion of Tradition and Elegance', 'maroon-anarkali-lucknowi-chikankari-work-lehenga-a-beautiful-fusion-of-tradition-and-elegance', 'Step into timeless elegance with this Maroon Anarkali Lucknowi Chikankari Work Lehenga, an exquisite blend of traditional artistry and modern design. Featuring delicate handcrafted Chikankari embroidery on rich maroon fabric, this lehenga redefines ethnic fashion with grace and sophistication. The Anarkali-style flair adds regal charm, making it perfect for weddings, festive occasions, and royal celebrations.\r\n\r\nDesigned for the modern woman who cherishes her roots, this ensemble boasts intricate threadwork, a flowing silhouette, and a luxurious drape that flatters every body type. Whether you’re attending a wedding or hosting a festive soirée, this lehenga promises to make a grand statement.', 199.00, 'Lehenga Choli', '1784290431297-139257702.webp', '2026-07-23 10:07:14', 80, '[\"1784290431297-204118306.webp\"]', '2026-07-23 10:07:14', NULL),
(27, 'Blue Color Sequence Embroidery Lehenga Choli for Wedding Function – Elegance in Every Stitch', 'blue-color-sequence-embroidery-lehenga-choli-for-wedding-function-elegance-in-every-stitch', 'Make a stunning statement at any wedding or festive celebration with this Blue Color Sequin Embroidered Lehenga Choli, crafted to perfection for the modern Indian woman. Designed with elegance and tradition in mind, this outfit features intricate sequin, thread, and zari embroidery on premium fabric that offers both style and comfort.\r\n\r\nThe luxurious blue hue brings a regal touch, while the flared lehenga silhouette, embellished dupatta, and perfectly tailored choli make it an ideal choice for wedding receptions, sangeet nights, festive occasions, and designer bridal functions.\r\n\r\nWhether you’re the bride, bridesmaid, or wedding guest, this ensemble ensures all eyes are on you — a blend of heritage craftsmanship and contemporary flair.', 299.00, 'Lehenga Choli', '1784290518023-754194479.webp', '2026-07-23 10:07:14', 55, '[\"1784290518024-569305586.webp\"]', '2026-07-23 10:07:14', NULL),
(28, 'The Beauty Of Blossoms In This Floral Wonder Lehenga Choli', 'the-beauty-of-blossoms-in-this-floral-wonder-lehenga-choli', 'Embrace the timeless charm of nature with “The Beauty of Blossoms” Floral Wonder Lehenga Choli – a masterpiece that blends tradition and elegance. This enchanting ensemble features a richly embroidered lehenga adorned with delicate floral patterns, paired with a beautifully designed choli and dupatta that exude grace and sophistication.\r\n\r\nPerfect for weddings, receptions, festive celebrations, or sangeet nights, this lehenga choli ensures you stand out with its vibrant hues and fine craftsmanship. Made with premium fabric and precision tailoring, it offers both comfort and couture-like glamour. Style it with traditional jewelry and soft curls for a breathtaking ethnic look.', 299.00, 'Lehenga Choli', '1784290582029-639970535.webp', '2026-07-23 10:07:14', 77, '[\"1784290582030-170982254.webp\"]', '2026-07-23 10:07:14', NULL),
(29, 'Heavy Embroidered Lehenga with Gota Lace Crop Top and Dupatta – Exquisite Traditional Elegance', 'heavy-embroidered-lehenga-with-gota-lace-crop-top-and-dupatta-exquisite-traditional-elegance', 'Turn every head with this exquisitely crafted Heavy Embroidered Lehenga set, featuring a luxurious gota lace crop top, richly detailed embroidery, and a flowing dupatta. Designed for grandeur, this ensemble blends traditional craftsmanship with modern elegance, perfect for weddings, receptions, festivals, or bridal occasions.\r\n\r\nThe lehenga features intricate zari, sequin, and thread embroidery on premium fabric that adds depth and royalty to your look. The gota lace crop top elevates the ethnic appeal, while the lightweight dupatta with embroidered borders completes this timeless outfit.\r\n\r\nWhether you’re the bride, bridesmaid, or guest, this lehenga ensures you leave an unforgettable impression with style and grace.', 149.00, 'Lehenga Choli', '1784290627035-69272471.webp', '2026-07-23 10:07:14', 25, '[\"1784290627036-256455002.webp\"]', '2026-07-23 10:07:14', NULL),
(30, 'Pink Print Net Readymade Lehenga', 'pink-print-net-readymade-lehenga', 'Elevate your festive wardrobe with this stunning Pink Print Net Readymade Lehenga – a perfect blend of elegance, comfort, and traditional charm. Crafted from premium quality net fabric, this lehenga showcases intricate printed detailing that adds a royal touch to your ethnic style. The semi-stitched design offers a flattering fit for all body types, making it ideal for weddings, receptions, sangeet, or festive gatherings.\r\n\r\nFeaturing a flowy silhouette, breathable lining, and a soft elastic waistband, this lehenga ensures all-day comfort without compromising on glam. Pair it with a matching blouse and embellished dupatta to complete your statement look.', 149.00, 'Lehenga Choli', '1784290696239-336552088.webp', '2026-07-23 10:07:14', 45, '[\"1784290696240-634210659.webp\"]', '2026-07-23 10:07:14', NULL),
(31, 'Blue Velvet Sulwar Suit', 'blue-velvet-sulwar-suit', 'Step into elegance with our Royal Blue Velvet Salwar Suit, a perfect blend of tradition and glamour. Crafted from premium velvet fabric, this suit exudes luxury with its rich texture and intricate embroidery. Designed for weddings, festive occasions, or formal gatherings, the suit features a beautifully embroidered kameez, a matching salwar, and a complementing dupatta that adds a graceful finish to your ethnic ensemble.\r\n\r\nWith its soft feel and regal look, this velvet salwar suit will make you stand out effortlessly—whether it’s a wedding celebration, cultural event, or evening function.', 149.00, 'Salwar Suit', '1784290834150-281719534.webp', '2026-07-23 10:07:14', 88, '[\"1784290834154-484794568.webp\"]', '2026-07-23 10:07:14', NULL),
(32, 'Women Viscose Rayon Marron Sherwani Dupatta Set', 'women-viscose-rayon-marron-sherwani-dupatta-set', 'Turn heads at every festive occasion with this elegant Women’s Viscose Rayon Maroon Sherwani Dupatta Set. Designed for modern women who appreciate timeless ethnic fashion, this set blends classic Sherwani silhouette with contemporary comfort. Crafted from premium viscose rayon fabric, it features intricate detailing, a flattering tailored fit, and a graceful dupatta to elevate your look. Perfect for weddings, parties, or festive celebrations, this maroon ensemble is all about royalty, tradition, and effortless style.\r\n\r\nWhether you’re dressing up for a Diwali celebration, a family gathering, or a bridesmaid role—this ethnic set promises grace and confidence with every step.', 99.00, 'Salwar Suit', '1784290889291-346022299.webp', '2026-07-23 10:07:14', 99, '[\"1784290889291-705289312.webp\"]', '2026-07-23 10:07:14', NULL),
(33, 'Women’s Rayon Embroidered Kurta, Pant with Dupatta Set', 'women-s-rayon-embroidered-kurta-pant-with-dupatta-set', 'Elevate your ethnic wardrobe with this elegant Women’s Rayon Embroidered Kurta, Pant, and Dupatta Set – where traditional craftsmanship meets modern comfort. Made from premium-quality rayon fabric, the kurta features intricate embroidery on the front, adding a touch of grace to your festive or casual look. The straight-fit pants offer all-day ease, while the lightweight, matching dupatta completes the ensemble with finesse.\r\n\r\nPerfect for festive occasions, family gatherings, office wear, or casual outings, this 3-piece set is a wardrobe essential that blends style, comfort, and durability effortlessly.', 129.00, 'Salwar Suit', '1784290978467-422544301.webp', '2026-07-23 10:07:14', 50, '[\"1784290978468-100967497.webp\"]', '2026-07-23 10:07:14', NULL),
(34, 'Drape Silk Kurti Set', 'drape-silk-kurti-set', 'Turn heads with elegance and grace in this luxurious Drape Silk Kurti Set, crafted for the modern woman who values both comfort and sophistication. Made from premium-quality silk blend fabric, this kurti drapes beautifully around the body, offering a flattering silhouette that fits all occasions—be it festive gatherings, family functions, or casual chic evenings.\r\n\r\nThe set features a flowy draped design that enhances movement, intricate embroidery or print detailing for a rich ethnic look, and comes paired with a coordinated bottom and matching dupatta for a complete ensemble. Breathable, soft, and effortlessly stylish, this kurti set combines traditional charm with contemporary tailoring.\r\n\r\nPerfect for festive wear, ethnic day events, or elegant casual outings, this is a must-have addition to your ethnic wardrobe.', 129.00, 'Salwar Suit', '1784291225365-476324564.webp', '2026-07-23 10:07:14', 65, '[\"1784291225365-918977326.webp\"]', '2026-07-23 10:07:14', NULL),
(35, 'Embroidery Un Stitched Salwar Set', 'embroidery-un-stitched-salwar-set', 'Step into timeless elegance with this Embroidered Unstitched Salwar Suit Set, a perfect blend of traditional charm and modern sophistication. Crafted from high-quality fabric, this unstitched suit features intricate thread embroidery that adds a graceful touch to your ethnic wardrobe. Whether it’s a festive celebration, a family gathering, or a casual day out, this outfit lets you design your look your way.\r\n\r\nPair it with your favorite accessories and get it tailored to your perfect fit – style it as a straight-cut, A-line, or even Anarkali silhouette. With its versatile design and breathable fabric, this ensemble offers unmatched comfort and style in every stitch.', 129.00, 'Salwar Suit', '1784291284326-902441914.webp', '2026-07-23 10:07:14', 85, '[\"1784291284328-849560956.webp\"]', '2026-07-23 10:07:14', NULL),
(36, 'White Salwar Suit', 'white-salwar-suit', 'Step into timeless elegance with this beautifully crafted White Salwar Suit, designed for women who appreciate simplicity, grace, and comfort. Made from premium-quality fabric, this ensemble blends traditional charm with modern tailoring. Ideal for festive occasions, office wear, or casual outings, its breathable material and flattering silhouette ensure all-day comfort with effortless style.\r\n\r\nAccented with minimal embroidery and paired with a soft dupatta, this white salwar suit is a wardrobe essential for every season. Whether you’re attending a puja, a family gathering, or a formal lunch, this outfit radiates sophistication and purity. Style it with jhumkas and juttis to complete the look!', 129.00, 'Salwar Suit', '1784291332335-23584273.webp', '2026-07-23 10:07:14', 98, '[\"1784291332338-13059123.webp\"]', '2026-07-23 10:07:14', NULL),
(37, 'Pure Shimmer Silk Kurta Set with Intricate Knot Work – Effortlessly Glamorous', 'pure-shimmer-silk-kurta-set-with-intricate-knot-work-effortlessly-glamorous', 'Elevate your ethnic style with this Pure Shimmer Silk Kurta Set, exquisitely crafted for modern elegance and timeless grace. Designed from premium shimmer silk fabric, this ensemble blends traditional craftsmanship with a glamorous twist. The intricate hand knot work adds luxurious texture and detail, making it perfect for weddings, festivals, or special occasions. Lightweight, breathable, and effortless to carry, it drapes beautifully on every body type. Whether you’re attending a cocktail soirée or a cultural celebration, this kurta set ensures you shine with understated sophistication.', 129.00, 'Salwar Suit', '1784291386868-838155845.webp', '2026-07-23 10:07:14', 87, '[\"1784291386871-21509029.webp\"]', '2026-07-23 10:07:14', NULL),
(38, 'Red colour heavy handwork kurta set with dupatta', 'red-colour-heavy-handwork-kurta-set-with-dupatta', 'Turn heads in this exquisite red heavy handwork kurta set with dupatta – a perfect blend of tradition and luxury. Crafted from premium fabric, this ethnic ensemble features intricate hand embroidery, sequin detailing, and artisanal craftsmanship. The flattering silhouette is complemented by a beautifully adorned dupatta, making it ideal for weddings, festivals, sangeet nights, or bridal occasions. Pair it with statement jewelry and heels for an unforgettable festive look.', 129.00, 'Salwar Suit', '1784291468577-866743929.webp', '2026-07-23 10:07:14', 52, '[\"1784291468577-917745018.webp\",\"1784291468580-904755213.webp\"]', '2026-07-23 10:07:14', NULL),
(39, 'STUNNING CHINNON HANDWORK A LINE SUIT', 'stunning-chinnon-handwork-a-line-suit', 'Elevate your ethnic wardrobe with this Stunning Chinon Handwork A-Line Suit, a perfect blend of grace, glamour, and timeless tradition. Crafted from premium Chinon fabric, this suit features intricate hand embroidery that exudes royal elegance and artisan finesse. The flowing A-line silhouette offers a flattering drape, making it ideal for festive occasions, weddings, and evening functions.\r\n\r\nThe lightweight yet luxurious fabric ensures comfort without compromising on style, while the handcrafted detailing reflects the finesse of Indian heritage. Pair it with statement jewelry and embellished juttis for a head-turning look that speaks volumes.\r\n\r\nWhether you’re attending a wedding or celebrating a festival, this designer Chinon suit is your go-to for effortless elegance.', 149.00, 'Salwar Suit', '1784291531317-651842674.webp', '2026-07-23 10:07:14', 87, '[\"1784291531318-225713786.webp\"]', '2026-07-23 10:07:14', NULL),
(40, 'STUNNING CHINNON HANDWORK A LINE SUIT(ORANGE)', 'stunning-chinnon-handwork-a-line-suit-orange', 'Step into timeless elegance with this Stunning Chinnon Handwork A-Line Suit in radiant orange, designed to turn heads at any festive or formal occasion. Crafted from luxurious chinnon fabric, this suit features intricate hand embroidery and embellishments that reflect traditional artistry with a modern twist.\r\n\r\nThe A-line silhouette flatters every body type, offering comfort with a touch of grace. Whether it’s a wedding, festival, or evening event, this outfit delivers the perfect blend of style, comfort, and sophistication.\r\n\r\nPair it with statement earrings and embellished heels to complete the look. A must-have piece in every woman’s ethnic wardrobe.', 149.00, 'Salwar Suit', '1784291596865-718869347.webp', '2026-07-23 10:07:14', 80, '[\"1784291596865-213911142.webp\"]', '2026-07-23 10:07:14', NULL),
(42, 'Darsh kakadiya ', 'darsh-kakadiya', 'zs,nsdkjfbsdbfkjs', 200.00, 'Saree', '1784809971596-941928257.webp', '2026-07-23 12:32:51', 30, '[\"1784809971602-423800207.webp\",\"1784809971611-569786793.webp\",\"1784809971612-97860920.webp\",\"1784809971615-185494382.webp\"]', '2026-07-23 12:32:51', NULL),
(44, 'ETA Ultimate Combination Mineral Makeup Set 71 Colors ', 'eta-ultimate-combination-mineral-makeup-set-71-colors', 'All In One Makeup Kit for Women – Eyeshadow, Blush, Lip Color & Face Powder | 6155 Name: All In One Makeup Kit for Women – Eyeshadow, Blush, Lip Color & Face Powder | 6155 Brand: BLUSHIS Color: Multicolor Net Quantity (N): 1 Create stunning makeup looks with this All In One Makeup Kit for Women, designed with everything you need for eye, face, and lip makeup in one compact palette. This multiuse beauty kit includes vibrant eyeshadow shades, blush colors, lip shades, face powder, and applicators for a complete professional makeup experience. Country of Origin: India\r\n\r\n\r\n', 99.00, 'Makeup', '1787402394457-236432181.webp', '2026-08-22 12:39:54', 25, '[\"1787402394460-764193737.webp\"]', '2026-08-22 12:39:54', NULL),
(45, 'All In One Makeup Kit with Mirror', 'all-in-one-makeup-kit-with-mirror', 'Upgrade your beauty collection with this elegant all-in-one makeup kit designed for makeup lovers who enjoy convenience and style. Featuring a beautifully organized case with multiple makeup essentials, this kit makes it easy to create stunning looks for everyday wear or special occasions. The stylish portable case opens into a complete beauty station, giving you quick access to a wide range of colors and products. From vibrant shades to soft natural tones, the variety allows you to experiment with different makeup styles based on your mood, outfit, or event. Designed for both beginners and experienced users, this makeup kit helps simplify your beauty routine. The organized layout keeps everything neatly arranged, so you can easily find what you need without clutter or mess during application. Its compact yet spacious design makes it ideal for home use as well as travel. Whether you are getting ready for work, a party, a wedding, or a vacation, this kit ensures your favorite beauty essentials stay in one secure and convenient place.\r\n\r\n', 89.00, 'Makeup', '1787402513794-247326941.webp', '2026-08-22 12:41:53', 78, '[\"1787402513795-552539878.webp\"]', '2026-08-22 13:12:32', NULL),
(46, 'Carzy Girl 5in1 Book-Style Foldable Makeup Palette Set', 'carzy-girl-5in1-book-style-foldable-makeup-palette-set', '5-Layer Book-Style Makeup Palette Set! From subtle daytime looks to bold evening glam, this one palette has you covered with versatile eyeshadows, sparkling highlights, seamless contours, and popping blushes. Experience the ultimate makeup joy with Bajajbeautyshop ! Our premium mineral-based formula ensures smooth application, exceptional color payoff, and lasting wear for up to 24 hours. It\'s sweat-proof, water-resistant, and feels weightless on your skin - perfect for all-day confidence! Travel-friendly and fuss-free! The unique book-style packaging of this palette allows for organization and on-the-go convenience. No more rummaging through a cluttered makeup bag - just fold it up and you\'re ready to slay wherever you are! Unleash your inner artist, play with colors, and express your unique style with this all-in-one palette that caters to every makeup need. Transform your beauty routine with the Bajajbeautyshop Carzy Girl 5-in-1 Foldable Makeup Palette Set – the ultimate all-in-one makeup kit for women and girls. This book-style foldable palette features 48 richly pigmented eyeshadows, 6 flattering blushers, 6 luminous highlighters, 9 hydrating lip shades, and 6 versatile eyebrow & concealer shades – everything you need in one sleek, portable palette. Whether you\'re a beginner or a pro, this professional makeup palette is designed for full-face coverage and effortless application. From subtle daily looks to bold bridal or party styles, achieve flawless results every time. The compact, travel-friendly design is perfect for vacations, on-the-go glam, or gifting. Made with long-lasting, skin-friendly formulas, it ensures a smooth, smudge-proof finish that lasts all day. Ideal for all occasions – weddings, festivals, photoshoots, or everyday wear. Upgrade your beauty game with this multi-purpose makeup palette – a must-have for every makeup lover.\r\n\r\n', 79.00, 'Makeup', '1787402620806-768045719.webp', '2026-08-22 12:43:40', 89, '[\"1787402620807-196729122.webp\"]', '2026-08-22 13:12:17', NULL);
